1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "$id": "nui-hunter-case-v1",
4	  "title": "Núi Tiền Case Schema",
5	  "description": "Each case is a verifiable opportunity with causal mechanism + replication path. NEVER write a case without provenance URLs.",
6	  "type": "object",
7	  "required": [
8	    "case_id",
9	    "title_vn",
10	    "domain",
11	    "founder_profile_fit",
12	    "causal_mechanism",
13	    "replication_path",
14	    "failure_modes",
15	    "real_references",
16	    "evidence_sources",
17	    "last_verified",
18	    "confidence"
19	  ],
20	  "properties": {
21	    "case_id": {"type": "string", "description": "kebab-case unique id"},
22	    "title_vn": {"type": "string"},
23	    "title_en": {"type": "string"},
24	    "domain": {"type": "string", "description": "free-form, NOT a fixed taxonomy"},
25	    "founder_profile_fit": {
26	      "type": "object",
27	      "properties": {
28	        "capital_min_usd": {"type": "number"},
29	        "capital_max_usd": {"type": "number"},
30	        "skill_required": {"type": "array", "items": {"type": "string"}},
31	        "geo_advantage": {"type": "array", "items": {"type": "string"}},
32	        "geo_disadvantage": {"type": "array", "items": {"type": "string"}},
33	        "language_required": {"type": "string"},
34	        "network_required": {"type": "array", "items": {"type": "string"}},
35	        "time_to_first_dollar_days": {"type": "number"},
36	        "monthly_time_required_hours": {"type": "number"}
37	      }
38	    },
39	    "causal_mechanism": {
40	      "type": "string",
41	      "description": "WHY this works. NOT what — why. Mechanism + prerequisites + how revenue is captured."
42	    },
43	    "mountain_test_v2": {
44	      "type": "object",
45	      "description": "Binary mountain test. Supersedes five_property_test. Mountain = >=$10K/mo NET + compounding component + real pulse reply.",
46	      "required": ["q1_existing_10k_proof", "q2_unfair_advantage", "asymmetry_ratio", "verdict"],
47	      "properties": {
48	        "q1_existing_10k_proof": {
49	          "type": "object",
50	          "required": ["answer", "evidence_url", "monthly_net_usd"],
51	          "properties": {
52	            "answer": {"enum": ["yes", "no", "insufficient_data"]},
53	            "evidence_url": {"type": "string"},
54	            "monthly_net_usd": {"type": "number", "description": ">=10000 to qualify"},
55	            "founder_name": {"type": "string"}
56	          }
57	        },
58	        "q2_unfair_advantage": {
59	          "type": "object",
60	          "required": ["answer", "advantage", "why_99pct_lack"],
61	          "properties": {
62	            "answer": {"enum": ["yes", "no", "weak"]},
63	            "advantage": {"type": "string"},
64	            "why_99pct_lack": {"type": "string"}
65	          }
66	        },
67	        "asymmetry_ratio": {
68	          "type": "object",
69	          "required": ["upside_p50_usd", "downside_p50_usd", "ratio"],
70	          "properties": {
71	            "upside_p50_usd": {"type": "number"},
72	            "downside_p50_usd": {"type": "number"},
73	            "ratio": {"type": "number", "description": ">=10 = mountain candidate"}
74	          }
75	        },
76	        "compounding_component": {
77	          "type": "object",
78	          "required": ["type", "evidence"],
79	          "properties": {
80	            "type": {"enum": ["data", "relationship", "distribution-lock", "ip", "rare-skill", "none"]},
81	            "evidence": {"type": "string"}
82	          }
83	        },
84	        "verdict": {"enum": ["MOUNTAIN", "PROVISIONAL_MOUNTAIN", "SIDE_HUSTLE", "INSUFFICIENT_SIGNAL", "KILL"]}
85	      }
86	    },
87	    "pulse_replies": {
88	      "type": "array",
89	      "description": "Real outside-in inquiry replies. Required for MOUNTAIN verdict.",
90	      "items": {
91	        "type": "object",
92	        "required": ["channel", "sent_date", "received_date", "reply_text", "buyer_intent"],
93	        "properties": {
94	          "channel": {"enum": ["alibaba_rfq", "etsy_dm", "reddit", "facebook_group", "zalo_group", "linkedin", "cold_email", "phone", "other"]},
95	          "sent_date": {"type": "string", "format": "date"},
96	          "received_date": {"type": "string", "format": "date"},
97	          "reply_text": {"type": "string"},
98	          "buyer_intent": {"enum": ["buying_now", "researching", "tire_kicker", "no_intent", "spam"]}
99	        }
100	      }
101	    },
102	    "five_property_test": {
103	      "type": "object",
104	      "description": "DEPRECATED — superseded by mountain_test_v2. Kept for back-compat with existing cases.",
105	      "required": ["tam", "trajectory_5y", "moat", "achievability", "saturation"],
106	      "properties": {
107	        "tam": {"type": "object", "properties": {"score_0_10": {"type": "number"}, "evidence": {"type": "string"}, "source_urls": {"type": "array"}}},
108	        "trajectory_5y": {"type": "object", "properties": {"direction": {"enum": ["RISING", "STABLE", "DECLINING", "VOLATILE"]}, "score_0_10": {"type": "number"}, "evidence": {"type": "string"}, "source_urls": {"type": "array"}}},
109	        "moat": {"type": "object", "properties": {"types": {"type": "array", "items": {"enum": ["geographic", "supplier-lock", "brand", "ip", "network-effect", "switching-cost", "regulatory", "data", "distribution", "founder-skill"]}}, "score_0_10": {"type": "number"}, "evidence": {"type": "string"}}},
110	        "achievability": {"type": "object", "properties": {"score_0_10": {"type": "number"}, "fits_profile": {"type": "boolean"}, "blockers": {"type": "array"}}},
111	        "saturation": {"type": "object", "properties": {"score_0_10": {"type": "number"}, "current_competitor_count": {"type": "string"}, "evidence": {"type": "string"}}}
112	      }
113	    },
114	    "overall_score": {"type": "number", "description": "0-50, sum of 5 properties (0-10 each)"},
115	    "replication_path": {
116	      "type": "array",
117	      "items": {"type": "object", "properties": {"step": {"type": "number"}, "action": {"type": "string"}, "duration_days": {"type": "number"}, "cost_usd": {"type": "number"}}}
118	    },
119	    "failure_modes": {
120	      "type": "array",
121	      "items": {"type": "object", "properties": {"mode": {"type": "string"}, "probability": {"enum": ["low", "medium", "high"]}, "mitigation": {"type": "string"}}}
122	    },
123	    "real_references": {
124	      "type": "array",
125	      "description": "Real founders/companies who proved this. EACH must have name + url + monthly_rev_estimate or other proof.",
126	      "items": {"type": "object", "properties": {"name": {"type": "string"}, "url": {"type": "string"}, "monthly_rev_usd_estimate": {"type": "string"}, "verified_via": {"type": "string"}}}
127	    },
128	    "evidence_sources": {
129	      "type": "array",
130	      "description": "URLs of trend data, market reports, founder interviews. ZERO fabrication tolerated."
131	    },
132	    "kill_criteria_7d": {"type": "array", "items": {"type": "string"}},
133	    "kill_criteria_30d": {"type": "array", "items": {"type": "string"}},
134	    "first_query": {"type": "string", "description": "User query that birthed this case"},
135	    "first_user_profile_hash": {"type": "string"},
136	    "last_verified": {"type": "string", "format": "date"},
137	    "verification_count": {"type": "number"},
138	    "confidence": {"type": "number", "minimum": 0, "maximum": 1},
139	    "anti_patterns": {"type": "array", "items": {"type": "string"}, "description": "What this case is NOT, common mis-applications"},
140	    "agents_fired": {
141	      "type": "array",
142	      "description": "RC-6: Track which specialist agents contributed to this case. Used for calibration and evolution quality assessment.",
143	      "items": {
144	        "type": "object",
145	        "required": ["agent_id", "fired_at"],
146	        "properties": {
147	          "agent_id": {"type": "string", "description": "Agent name (e.g., marc-rich, robert-kuok, chris-voss)"},
148	          "fired_at": {"type": "string", "format": "date-time"},
149	          "contribution_type": {"enum": ["analysis", "framework", "playbook", "negotiation", "verification"]},
150	          "key_insight": {"type": "string", "maxLength": 200}
151	        }
152	      }
153	    },
154	    "knowledge_fired": {
155	      "type": "array",
156	      "description": "Knowledge base entries (MM-*, SCH-*, etc.) that contributed to this case.",
157	      "items": {"type": "string"}
158	    },
159	    "side_door_paths": {
160	      "type": "array",
161	      "description": "Power-network side-door paths generated by Step 6.8.5 when KILL has relationship barriers.",
162	      "items": {
163	        "type": "object",
164	        "required": ["path_name", "chain", "timeline_weeks", "probability"],
165	        "properties": {
166	          "path_name": {"type": "string"},
167	          "chain": {"type": "array", "items": {"type": "string"}, "description": "Sequence: ['Founder', 'Role A at Org', 'TARGET Role']"},
168	          "scripts": {"type": "array", "items": {"type": "string"}, "description": "Exact script per chain link"},
169	          "value_exchanges": {"type": "array", "items": {"type": "string"}, "description": "What founder gives BEFORE asking, per link"},
170	          "timeline_weeks": {"type": "integer"},
171	          "kill_criterion": {"type": "string", "description": "If X doesn't happen by week Y, abandon"},
172	          "probability": {"type": "number", "minimum": 0, "maximum": 1, "description": "Honest estimate, most paths 0.10-0.30"}
173	        }
174	      }
175	    },
176	    "side_door_fired": {
177	      "type": "boolean",
178	      "description": "Whether Step 6.8.5 side-door scanner triggered for this case"
179	    },
180	    "voice_mode": {
181	      "type": "string",
182	      "enum": ["analyst", "operator"],
183	      "description": "Output voice mode used for this verdict",
184	      "default": "analyst"
185	    }
186	  }
187	}
